// Generated by `npm run index:game` from an installed copy of Stellaris.
// Game version: v4.5.2. File extensions and block keys only, no game content.
//
// Every type whose definitions vanilla keeps somewhere other than the root of
// a `.txt` file. The game lists `interface` for `.gfx` and `.gui` and `sound`
// for `.asset`, and reads a sprite only inside `spriteTypes = { }`; a
// definition written anywhere else is never opened, and nothing says so.

export interface VanillaPlacement {
  /** The extension of the files that hold most of vanilla's definitions. */
  readonly extension: string;
  /** The block that holds more than half of them, for a type read from inside one. */
  readonly container?: string;
}

